import{_ as r,o as d,c as a,a2 as e}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"01 · 创意","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/01-creative.md","filePath":"lab/shuangyu-fries/honey-butter/01-creative.md","lastUpdated":1787456457000}'),o={name:"lab/shuangyu-fries/honey-butter/01-creative.md"};function l(i,t,n,h,s,b){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="_01-·-创意" tabindex="-1">01 · 创意 <a class="header-anchor" href="#_01-·-创意" aria-label="Permalink to &quot;01 · 创意&quot;">​</a></h1><blockquote><p>本页只确认创意命题、互动机制与影片边界。通过后进入 <a href="./02-keyframes">02 · 关键帧</a>。</p></blockquote><h2 id="一句话创意" tabindex="-1">一句话创意 <a class="header-anchor" href="#一句话创意" aria-label="Permalink to &quot;一句话创意&quot;">​</a></h2><p>不再把「感官片」理解为光带、微粒、升格断裂与包装落版的组合，而是把整支片做成一道观众可以立即参加的<strong>声音选择题</strong>：</p><blockquote><p><strong>不看答案，你能听出哪一声是蜂蜜黄油味吗？</strong></p></blockquote><p>同一款薯条脆用三种方式发声：单根折断、双根同时折断、真实咬下。观众先选 A / B / C，影片再揭晓：</p><blockquote><p><strong>答案：都是。</strong></p><p><strong>味道听不见，脆可以。</strong></p></blockquote><p>形式本身就是产品证据。观众为了作答会主动打开声音、比较、重播和评论，不需要先看完一段广告才收到卖点。</p><h2 id="为什么换格式" tabindex="-1">为什么换格式 <a class="header-anchor" href="#为什么换格式" aria-label="Permalink to &quot;为什么换格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>旧版问题</th><th>当前处理</th></tr></thead><tbody><tr><td>20 秒横屏，主「咔嚓」到 8.8 秒后才出现</td><td>0.9 秒进入第一声，4.2 秒内完成三次核心感官证据</td></tr><tr><td>观众只是观看一组漂亮镜头</td><td>第一秒建立 A / B / C 选择任务</td></tr><tr><td>蜂蜜黄油靠光带与暖色抽象表达</td><td>口味只做身份线索，不用无依据原料画面解释</td></tr><tr><td>视觉奇观是主角，产品像特效载体</td><td>三组画面统一继承 P0 产品身份，声音在后期独立设计</td></tr><tr><td>单片看完即结束</td><td>可由真实评论继续生成回复片、复测片和声纹 remix</td></tr></tbody></table><h2 id="影片定位" tabindex="-1">影片定位 <a class="header-anchor" href="#影片定位" aria-label="Permalink to &quot;影片定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>产品</td><td>双宇食品「薯条脆」蜂蜜黄油味</td></tr><tr><td>片型</td><td>互动感官片 / 声音盲测 / 原生短视频</td></tr><tr><td>Big Idea</td><td><strong>蜂蜜黄油的味道不能隔着屏幕尝，但它有多脆，隔着屏幕也听得见。</strong></td></tr><tr><td>核心钩子</td><td><strong>哪一声是蜂蜜黄油味？</strong></td></tr><tr><td>答案反转</td><td><strong>都是。</strong></td></tr><tr><td>核心文案</td><td><strong>味道听不见，脆可以。</strong></td></tr><tr><td>核心诉求</td><td>蜂蜜黄油口味身份、干爽酥脆的声音记忆</td></tr><tr><td>画幅</td><td>9:16 竖屏，1080 × 1920；重要文字避开平台顶部、右侧与底部操作区</td></tr><tr><td>时长</td><td>12 秒主版；另剪 6 秒投放版与 4 条声纹素材</td></tr><tr><td>制作方式</td><td>产品实拍只作身份参考；画面以 AI 关键帧和图生视频生成，包装、文字、波形在后期合成</td></tr></tbody></table><h2 id="互动规则" tabindex="-1">互动规则 <a class="header-anchor" href="#互动规则" aria-label="Permalink to &quot;互动规则&quot;">​</a></h2><p>观众不需要学习玩法。第一帧同时给出问题和产品口味，随后按固定节拍听三声：</p><table tabindex="0"><thead><tr><th>选项</th><th>动作</th><th>声音性格</th><th>视觉职责</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>单根薯条脆从中央折断</td><td>短、亮、清晰</td><td>建立第一份「脆」证据</td></tr><tr><td><strong>B</strong></td><td>两根薯条脆同时折断</td><td>更厚、更密、带碎裂层次</td><td>与 A 形成可比较差异</td></tr><tr><td><strong>C</strong></td><td>真人近距离咬下一口</td><td>低频更完整、最接近真实食用体验</td><td>把测试从实验转回「想吃」</td></tr></tbody></table><p>三组画面必须继承同一张 P0 产品身份母版。A / B / C 的差异只来自动作与数量，不让模型在三个镜头里生成三种不同产品。最终声音在后期独立制作，不直接采用视频模型随机生成的声音。</p><h2 id="创意边界" tabindex="-1">创意边界 <a class="header-anchor" href="#创意边界" aria-label="Permalink to &quot;创意边界&quot;">​</a></h2><ul><li>蜂蜜黄油只作为确认后的口味身份，不用蜂蜜滴淋、蜂巢、蜂蜜罐或真实黄油块解释风味。</li><li>「脆」由同一产品母版下的三种动作、断面和后期声音共同建立。</li><li>所有正式动态从通过审核的本镜关键帧进入图生视频，不直接用文字盲生成整片。</li><li>Demo 只验证调性、动作顺序和节奏，不作为正式成片底料。</li><li>不伪造评论、点赞、测试结果或用户反馈。</li><li>最终包装只使用客户确认的蜂蜜黄油味终稿物料。</li></ul><h2 id="本步审核" tabindex="-1">本步审核 <a class="header-anchor" href="#本步审核" aria-label="Permalink to &quot;本步审核&quot;">​</a></h2><ul><li>[ ] 「哪一声是蜂蜜黄油味」可作为第一秒钩子</li><li>[ ] 「答案：都是」的反转清楚，不构成误导</li><li>[ ] 「味道听不见，脆可以」可作为核心文案</li><li>[ ] A / B / C 三种动作足以支撑互动</li><li>[ ] 同意按 P0 母版、关键帧、Demo、正式分镜的 AI 视频流程推进</li></ul><hr><p><strong>上一步</strong> ← <a href="./">项目总览</a> ｜ <strong>下一步</strong> → <a href="./02-keyframes">02 · 关键帧</a></p>',22)])])}const p=r(o,[["render",l]]);export{c as __pageData,p as default};
